                            t.HasCheckConstraint("ck_journal_entries_status", "status IN ('Draft','Posted','Reversed')");

                            t.HasCheckConstraint("ck_journal_entries_tamper_hash_length", "tamper_hash IS NULL OR tamper_hash ~ '^[0-9a-f]{64}$'");
                        });
