                            t.HasCheckConstraint("ck_movement_batches_rejection_reason", "(status = 'rejected') = (rejection_reason IS NOT NULL)");

                            t.HasCheckConstraint("ck_movement_batches_status", "status IN ('draft','confirmed','rejected','cancelled')");

                            t.HasCheckConstraint("ck_movement_batches_supplier_matches_kind", "kind <> 'voucher_exchange' OR supplier_id IS NOT NULL");

                            t.HasCheckConstraint("ck_movement_batches_surcharge_non_negative", "surcharge_uah >= 0");
                        });
                });

            modelBuilder.Entity("FuelFlow.Features.Vouchers.FuelVoucher", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uuid")
                        .HasColumnName("id");

                    b.Property<string>("AcquisitionSource")
                        .IsRequired()
                        .ValueGeneratedOnAdd()
                        .HasMaxLength(10)
                        .HasColumnType("character varying(10)")
                        .HasDefaultValue("direct")
                        .HasColumnName("acquisition_source")
                        .HasComment("The supply route this voucher came in on: direct, or through a partner. Immutable, andenforced by a trigger: the cost of a voucher is a function of where it came from, so anedited value does not merely relabel a row - it moves real money between two reports thatare supposed to be separate.");

                    b.Property<Guid?>("AssignedToUserId")
                        .HasColumnType("uuid")
                        .HasColumnName("assigned_to_user_id")
                        .HasComment("The customer who holds it.");

                    b.Property<string>("Brand")
                        .IsRequired()
                        .HasMaxLength(50)
                        .HasColumnType("character varying(50)")
                        .HasColumnName("brand")
                        .HasComment("The brand's NAME - what a report groups by and what a parser reads. The id below is whatthe database can check, and the two are the same fact written twice.");

                    b.Property<Guid>("BrandId")
                        .HasColumnType("uuid")
                        .HasColumnName("brand_id")
                        .HasComment("The brand's id - the key the text above is a copy of. The composite foreign key(fuel_type_id, brand_id) -> fuel_types(id, brand_id) is what refuses a row whose brandis not its fuel's brand. A nullable key would be a key the database does not check,because a foreign key with a NULL in it is not compared at all.");

                    b.Property<decimal?>("CostPerLiter")
                        .HasColumnType("numeric(10,4)")
                        .HasColumnName("cost_per_liter")
                        .HasComment("What this litre cost US, in UAH - the supplier's price, not our selling price.");

                    b.Property<DateTime>("CreatedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at_utc")
                        .HasComment("When the row was written.");

                    b.Property<DateOnly>("CustomerExpirationDate")
                        .HasColumnType("date")
                        .HasColumnName("customer_expiration_date")
                        .HasComment("What the customer was actually sold, and the date their wallet shows. Normally equal tosupplier_expiration_date; it is a separate column because we sell SHORT terms - avoucher with three months of real life may be sold with one week - and only this datemoves when the customer pays to extend it.");

                    b.Property<string>("DataKind")
                        .IsRequired()
                        .HasMaxLength(10)
                        .HasColumnType("character varying(10)")
                        .HasColumnName("data_kind")
                        .HasComment("Whether this row is business or a rehearsal: 'real' or 'qa'.");

                    b.Property<Guid>("FuelTypeId")
                        .HasColumnType("uuid")
                        .HasColumnName("fuel_type_id")
                        .HasComment("The fuel this voucher is for.");

                    b.Property<string>("HolderKind")
                        .IsRequired()
                        .ValueGeneratedOnAddOrUpdate()
                        .HasMaxLength(16)
                        .HasColumnType("character varying(16)")
                        .HasColumnName("holder_kind")
                        .HasComputedColumnSql("CASE\n    WHEN worker_user_id IS NOT NULL THEN 'Worker'\n    WHEN legal_entity_id IS NOT NULL AND assigned_to_user_id IS NOT NULL THEN 'Company'\n    WHEN assigned_to_user_id IS NOT NULL THEN 'Personal'\n    ELSE 'Stock'\nEND", true)
                        .HasComment("Who may redeem it: the customer, or the worker it was issued to.");

                    b.Property<Guid?>("ImportJobId")
                        .HasColumnType("uuid")
                        .HasColumnName("import_job_id")
                        .HasComment("The import it came from.");

                    b.Property<bool>("IsDeleted")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("boolean")
                        .HasDefaultValue(false)
                        .HasColumnName("is_deleted")
                        .HasComment("Soft delete. The row stays: the paper was real, and the record of it has to survive thedelete.");

                    b.Property<DateTime?>("IssuedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("issued_at_utc")
                        .HasComment("When this voucher was handed to a worker by a company owner. Set once, on issue; nevermoved afterwards. A column of its own rather than a reading of updated_at_utc, becauseevery mutation - a block, a recall, a deactivate - clobbers updated_at_utc, and a usagereport that answered 'when did I receive this' off it would move the date every time theowner touched it.");

                    b.Property<Guid?>("LegalEntityId")
                        .HasColumnType("uuid")
                        .HasColumnName("legal_entity_id")
                        .HasComment("The company the voucher was sold to.");

                    b.Property<decimal>("Liters")
                        .HasColumnType("numeric(10,2)")
                        .HasColumnName("liters")
                        .HasComment("How many litres this voucher's paper is for.");

                    b.Property<Guid?>("OrderId")
                        .HasColumnType("uuid")
                        .HasColumnName("order_id")
                        .HasComment("The order it was sold with, when it was sold with one.");

                    b.Property<Guid?>("QrParametersId")
                        .HasColumnType("uuid")
                        .HasColumnName("qr_parameters_id")
                        .HasComment("The QR parameters read from the original code - the geometry needed to regenerate it. NULLwhen the code was not read.");

                    b.Property<byte[]>("QrPayload")
                        .IsRequired()
                        .HasColumnType("bytea")
                        .HasColumnName("qr_payload")
                        .HasComment("The supplier's QR code, verbatim - the redeemable material. Stored as AES-GCMciphertext: what sits in the column is nonce, tag and ciphertext concatenated.");

                    b.Property<byte[]>("QrPayloadSha256")
                        .IsRequired()
                        .HasColumnType("bytea")
                        .HasColumnName("qr_payload_sha256")
                        .HasComment("SHA-256 of the QR payload, carrying the deduplication the ciphertext cannot. Encryptedbytes cannot be compared - AES-GCM produces a fresh nonce every time, so the same QRencrypts differently every time - so the uniqueness index moved here. A hash is notreversible, and it is still a fingerprint of a redeemable code, so it is not somethingto log or expose.");

                    b.Property<string>("Status")
                        .IsRequired()
                        .HasMaxLength(32)
                        .HasColumnType("character varying(32)")
                        .HasColumnName("status")
                        .HasComment("Where the voucher stands: assigned, used, expired, blocked and the rest.");

                    b.Property<DateOnly>("SupplierExpirationDate")
                        .HasColumnType("date")
                        .HasColumnName("supplier_expiration_date")
                        .HasComment("The real term of the SUPPLIER's voucher, read verbatim from the printed document atimport. It is the hard ceiling on everything we may promise: it bounds how long stockstays sellable and how far a customer's renewal may extend. Set once at import and nevermoved afterwards - a supplier voucher cannot be extended by us.");

                    b.Property<Guid?>("SupplierId")
                        .HasColumnType("uuid")
                        .HasColumnName("supplier_id")
                        .HasComment("Who we bought it from.");

                    b.Property<DateTime>("UpdatedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at_utc")
                        .HasComment("When it was last changed.");

                    b.Property<DateTime?>("UsedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("used_at_utc")
                        .HasComment("When this voucher was actually refuelled with. Set once, when it is marked used; nevermoved afterwards. NULL while the voucher is still unused.");

                    b.Property<decimal?>("VerificationMismatchPercent")
                        .HasColumnType("numeric(5,4)")
                        .HasColumnName("verification_mismatch_percent")
                        .HasComment("How far the verification of this voucher's modules disagreed, as a percentage. NULL whenit was never verified.");

                    b.Property<int?>("VerificationMismatchedModules")
                        .HasColumnType("integer")
                        .HasColumnName("verification_mismatched_modules")
                        .HasComment("How many modules disagreed.");

                    b.Property<int?>("VerificationTotalModules")
                        .HasColumnType("integer")
                        .HasColumnName("verification_total_modules")
                        .HasComment("How many modules were checked.");

                    b.Property<string>("VoucherNumber")
                        .IsRequired()
                        .HasMaxLength(100)
                        .HasColumnType("character varying(100)")
                        .HasColumnName("voucher_number")
                        .HasComment("The voucher's own number, as the supplier printed it.");

                    b.Property<Guid?>("WorkerUserId")
                        .HasColumnType("uuid")
                        .HasColumnName("worker_user_id")
                        .HasComment("The worker it was issued to.");

                    b.Property<uint>("xmin")
                        .IsConcurrencyToken()
                        .ValueGeneratedOnAddOrUpdate()
                        .HasColumnType("xid")
                        .HasColumnName("xmin");

                    b.HasKey("Id");

                    b.HasIndex("CustomerExpirationDate")
                        .HasDatabaseName("ix_fuel_vouchers_customer_expiration_date");

                    b.HasIndex("ImportJobId")
                        .HasDatabaseName("ix_fuel_vouchers_import_job_id");

                    b.HasIndex("OrderId")
                        .HasDatabaseName("ix_fuel_vouchers_order_id");

                    b.HasIndex("QrParametersId")
                        .HasDatabaseName("ix_fuel_vouchers_qr_parameters_id");

                    b.HasIndex("QrPayloadSha256")
                        .IsUnique()
                        .HasDatabaseName("ix_fuel_vouchers_qr_payload_sha256")
                        .HasFilter("is_deleted = false");

                    b.HasIndex("SupplierExpirationDate")
                        .HasDatabaseName("ix_fuel_vouchers_supplier_expiration_date");

                    b.HasIndex("SupplierId")
                        .HasDatabaseName("ix_fuel_vouchers_supplier_id");

                    b.HasIndex("VoucherNumber")
                        .IsUnique()
                        .HasDatabaseName("ix_fuel_vouchers_voucher_number")
                        .HasFilter("is_deleted = false");

                    b.HasIndex("WorkerUserId")
                        .HasDatabaseName("ix_fuel_vouchers_worker_user_id");

                    b.HasIndex("AssignedToUserId", "Status")
                        .HasDatabaseName("ix_fuel_vouchers_assigned_to_user_id_status");

                    b.HasIndex("CreatedAtUtc", "Id")
                        .IsDescending(true, false)
                        .HasDatabaseName("ix_fuel_vouchers_created_at_utc_id");

                    b.HasIndex("FuelTypeId", "BrandId")
                        .HasDatabaseName("ix_fuel_vouchers_fuel_type_id_brand_id");

                    b.HasIndex("FuelTypeId", "Status", "IsDeleted")
                        .HasDatabaseName("ix_fuel_vouchers_fuel_type_id_status_is_deleted");

                    b.HasIndex("Status", "DataKind", "IsDeleted")
                        .HasDatabaseName("ix_fuel_vouchers_status_data_kind_is_deleted");

                    b.HasIndex("Brand", "FuelTypeId", "Liters", "Status")
                        .HasDatabaseName("ix_fuel_vouchers_brand_fuel_type_id_liters_status");

                    b.HasIndex("LegalEntityId", "WorkerUserId", "Status", "IsDeleted")
                        .HasDatabaseName("ix_fuel_vouchers_legal_entity_id_worker_user_id_status_is_dele~");

                    b.ToTable("fuel_vouchers", null, t =>
                        {
                            t.HasCheckConstraint("ck_fuel_vouchers_acquisition_source", "acquisition_source IN ('direct', 'partner')");

                            t.HasCheckConstraint("ck_fuel_vouchers_data_kind", "data_kind IN ('real', 'qa')");

                            t.HasCheckConstraint("ck_voucher_cost_non_negative", "cost_per_liter IS NULL OR cost_per_liter >= 0");

                            t.HasCheckConstraint("ck_voucher_customer_term_within_supplier_term", "customer_expiration_date <= supplier_expiration_date");

                            t.HasCheckConstraint("ck_voucher_held_has_order", "status NOT IN ('Assigned', 'Used', 'Blocked') OR order_id IS NOT NULL");

                            t.HasCheckConstraint("ck_voucher_holder", "(holder_kind = 'Stock'    AND assigned_to_user_id IS NULL)\nOR (holder_kind = 'Worker'   AND legal_entity_id IS NOT NULL AND worker_user_id IS NOT NULL)\nOR (holder_kind = 'Personal' AND worker_user_id IS NULL AND assigned_to_user_id IS NOT NULL)\nOR (holder_kind = 'Company'  AND worker_user_id IS NULL AND assigned_to_user_id IS NOT NULL)");

                            t.HasCheckConstraint("ck_voucher_liters_positive", "liters > 0");

                            t.HasCheckConstraint("ck_voucher_status", "status IN ('Imported', 'VerifiedWithWarnings', 'VerificationFailed', 'Available',\n           'Assigned', 'Used', 'Expired', 'Blocked', 'Deactivated')");
                        });
                });

            modelBuilder.Entity("FuelFlow.Features.Vouchers.Movements.VoucherMovement", b =>
                {
