                    b.Property<decimal?>("AppliedCostPerLiter")
                        .HasColumnType("numeric(12,4)")
                        .HasColumnName("applied_cost_per_liter")
                        .HasComment("The cost per litre stamped on the replacement when it arrived. A level, not a delta. Recorded AT THE TIME because it cannot be derived afterwards: fuel_vouchers.cost_per_liter is mutable and gets restamped.");

                    b.Property<Guid?>("BatchId")
                        .HasColumnType("uuid")
                        .HasColumnName("batch_id")
                        .HasComment("The settlement this movement is part of, when there was one. NULL for a movement anoperator or a customer performed on its own.");

                    b.Property<decimal?>("CostDeltaUah")
                        .HasColumnType("numeric(14,2)")
                        .HasColumnName("cost_delta_uah")
                        .HasComment("What this movement did to supplier-side cost, in UAH. NULL when cost did not move.Recorded AT THE TIME, from the values written in the same transaction, because it cannotbe derived afterwards: fuel_vouchers.cost_per_liter is mutable and gets overwritten, so'what did this voucher cost before' stops existing the moment the column is restamped.");

                    b.Property<string>("FromLocation")
                        .IsRequired()
                        .HasMaxLength(16)
                        .HasColumnType("character varying(16)")
                        .HasColumnName("from_location")
                        .HasComment("Where it was. See VoucherLocations.");

                    b.Property<string>("Kind")
                        .IsRequired()
                        .HasMaxLength(24)
                        .HasColumnType("character varying(24)")
                        .HasColumnName("kind")
                        .HasComment("What happened - issued, redeemed, blocked, released, and the rest. SeeVoucherMovementKinds.");

                    b.Property<Guid?>("LineItemId")
                        .HasColumnType("uuid")
                        .HasColumnName("line_item_id")
                        .HasComment("The order line this movement settled, for the renewal paths.");

                    b.Property<DateTime>("OccurredAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("occurred_at_utc")
                        .HasComment("When it happened.");

                    b.Property<Guid?>("OrderId")
                        .HasColumnType("uuid")
                        .HasColumnName("order_id")
                        .HasComment("The order this movement settled, when a customer paid for it. A bare uuid, no foreignkey: an audit row must not be the thing that blocks deleting its own subject.");

                    b.Property<string>("Reason")
                        .HasMaxLength(500)
                        .HasColumnType("character varying(500)")
                        .HasColumnName("reason")
                        .HasComment("Why, in the operator's words.");

                    b.Property<Guid?>("ReplacedByVoucherId")
                        .HasColumnType("uuid")
                        .HasColumnName("replaced_by_voucher_id")
                        .HasComment("The paper that took this voucher's place, when this paper was traded for another one. NULL for a movement that was not a trade - a sale, a return, an import. The row of the retired paper carries it, not the row of the successor.");

                    b.Property<decimal?>("SurchargeShareUah")
                        .HasColumnType("numeric(12,2)")
                        .HasColumnName("surcharge_share_uah")
                        .HasComment("This movement's share of the money a settlement moved: the doplata the operator paid the supplier for this pair of paper. NOT the settlement total - that lives on movement_batches.surcharge_uah, and the shares can sum to less than it.");

                    b.Property<string>("ToLocation")
                        .IsRequired()
                        .HasMaxLength(16)
                        .HasColumnType("character varying(16)")
                        .HasColumnName("to_location")
                        .HasComment("Where it is now. Never equal to from_location - that isck_voucher_movements_distinct_locations, and a row that says a paper moved from theshelf to the shelf is not a movement.");

                    b.Property<Guid>("VoucherId")
                        .HasColumnType("uuid")
                        .HasColumnName("voucher_id")
                        .HasComment("The piece of paper that moved.");

                    b.HasKey("Id");

                    b.HasIndex("BatchId")
                        .HasDatabaseName("ix_voucher_movements_batch")
                        .HasFilter("batch_id IS NOT NULL");

                    b.HasIndex("LineItemId")
                        .HasDatabaseName("ix_voucher_movements_line")
                        .HasFilter("line_item_id IS NOT NULL");

                    b.HasIndex("OrderId")
                        .HasDatabaseName("ix_voucher_movements_order")
                        .HasFilter("order_id IS NOT NULL");

                    b.HasIndex("ReplacedByVoucherId")
                        .HasDatabaseName("ix_voucher_movements_replaced_by")
                        .HasFilter("replaced_by_voucher_id IS NOT NULL");

                    b.HasIndex("VoucherId")
                        .IsUnique()
                        .HasDatabaseName("ix_voucher_movements_exchange_out")
                        .HasFilter("kind = 'exchange_out'");

                    b.HasIndex("VoucherId", "OccurredAtUtc")
                        .HasDatabaseName("ix_voucher_movements_voucher");

                    b.ToTable("voucher_movements", null, t =>
                        {
                            t.HasCheckConstraint("ck_voucher_movements_actor_is_somebody", "actor_user_id IS NULL OR actor_user_id <> '00000000-0000-0000-0000-000000000000'");

                            t.HasCheckConstraint("ck_voucher_movements_actor_kind", "actor_kind IN ('user','system')");

                            t.HasCheckConstraint("ck_voucher_movements_actor_named", "(actor_kind = 'user') = (actor_user_id IS NOT NULL)");

                            t.HasCheckConstraint("ck_voucher_movements_amount_non_negative", "amount_uah IS NULL OR amount_uah >= 0");

                            t.HasCheckConstraint("ck_voucher_movements_applied_cost_non_negative", "applied_cost_per_liter IS NULL OR applied_cost_per_liter >= 0");

                            t.HasCheckConstraint("ck_voucher_movements_distinct_locations", "from_location <> to_location");

                            t.HasCheckConstraint("ck_voucher_movements_kind", "kind IN ('deposit','issued','returned','replace_out','exchange_out','exchange_in','gift','recall')");

                            t.HasCheckConstraint("ck_voucher_movements_locations", "from_location IN ('pool','customer','supplier','company','worker') AND to_location IN ('pool','customer','supplier','company','worker')");

                            t.HasCheckConstraint("ck_voucher_movements_not_self_replaced", "replaced_by_voucher_id IS NULL OR replaced_by_voucher_id <> voucher_id");

                            t.HasCheckConstraint("ck_voucher_movements_surcharge_share_non_negative", "surcharge_share_uah IS NULL OR surcharge_share_uah >= 0");
                        });
                });

