            modelBuilder.Entity("FuelFlow.SharedKernel.Domain.FuelTypeEntity", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uuid")
                        .HasColumnName("id");

                    b.Property<bool>("AllowBelowCost")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("boolean")
                        .HasDefaultValue(false)
                        .HasColumnName("allow_below_cost")
                        .HasComment("Whether this fuel may be sold below what we pay. A manager's opt-in, per fuel, for a deliberate loss leader - the write path refuses such a sale without it.");

                    b.Property<decimal?>("BasePrice")
                        .HasColumnType("numeric(12,2)")
                        .HasColumnName("base_price")
                        .HasComment("The list price of the fuel per litre - the price before our discount. It is the reference the customer's saving is measured against. RETIRED: the reference is the COLUMN price next door, and the saving is computed from it. The column stays until the migration that drops it.");

                    b.Property<string>("BrandFuelCode")
                        .HasMaxLength(50)
                        .HasColumnType("character varying(50)")
                        .HasColumnName("brand_fuel_code");

                    b.Property<Guid>("BrandId")
                        .HasColumnType("uuid")
                        .HasColumnName("brand_id");

                    b.Property<DateTime>("CreatedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at_utc");

                    b.Property<DateTime?>("DeletedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("deleted_at_utc");

                    b.Property<decimal?>("DiscountPrice")
                        .HasColumnType("numeric(12,2)")
                        .HasColumnName("discount_price")
                        .HasComment("What the customer pays per litre. NULL means it is not set: the grade is in the catalogue and nobody has priced it yet. A price of zero is a price, and a price of zero means the customer takes the fuel for nothing - so the unset state is NULL and never 0.");

                    b.Property<bool>("IsDeleted")
                        .HasColumnType("boolean")
                        .HasColumnName("is_deleted");

                    b.Property<decimal?>("MarginPercent")
                        .HasColumnType("numeric(10,4)")
                        .HasColumnName("margin_percent")
                        .HasComment("The margin as a percentage, recorded for the operator's card. The price is computed from the ABSOLUTE margin (margin_uah_per_liter); this column does not feed the formula.");

                    b.Property<decimal?>("MarginUahPerLiter")
                        .HasColumnType("numeric(10,4)")
                        .HasColumnName("margin_uah_per_liter")
                        .HasComment("What we add per litre on top of what we pay. NULL means the margin is not stated, and a fuel with no stated cost OR no stated margin has no price of its own: it is shown at the column price, marked 'not in stock', and it cannot be sold.");

                    b.Property<decimal?>("MinDiscountPerLiter")
                        .HasColumnType("numeric(10,4)")
                        .HasColumnName("min_discount_per_liter")
                        .HasComment("The smallest discount we give the customer per litre, so that our price always sits below the column price - we are never dearer than the pump. RETIRED: the price is computed as min(cost + margin, pump), and this column no longer takes part in it. It stays until the migration that drops it.");

                    b.Property<string>("Name")
                        .IsRequired()
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("name");

                    b.Property<DateTime?>("PriceUpdatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("price_updated_at");

                    b.Property<Guid?>("PriceUpdatedByUserId")
                        .HasColumnType("uuid")
                        .HasColumnName("price_updated_by_user_id");

                    b.Property<decimal?>("PumpPricePerLiter")
                        .HasColumnType("numeric(10,4)")
                        .HasColumnName("pump_price_per_liter")
                        .HasComment("The COLUMN price - what the driver pays at the pump. It is the ceiling: our price is never above it, and it is the price the customer sees struck through when our price is below it.");

                    b.Property<decimal?>("SupplierPricePerLiter")
                        .HasColumnType("numeric(10,4)")
                        .HasColumnName("supplier_price_per_liter")
                        .HasComment("What WE pay the network per litre. NULL means the cost is not stated: the fuel is unpriced, and the below-cost guard has nothing to compare against.");

                    b.Property<DateTime>("UpdatedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at_utc")
                        .HasDefaultValueSql("now()");

                    b.HasKey("Id");

                    b.HasIndex("BrandId")
                        .HasDatabaseName("ix_fuel_types_brand_id");

                    b.HasIndex("Name")
                        .HasDatabaseName("ix_fuel_types_name");

                    b.HasIndex("BrandId", "BrandFuelCode")
                        .IsUnique()
                        .HasDatabaseName("ux_fuel_types_brand_brand_fuel_code")
                        .HasFilter("brand_fuel_code IS NOT NULL AND NOT is_deleted");

                    b.HasIndex("BrandId", "Name")
                        .IsUnique()
                        .HasDatabaseName("ux_fuel_types_brand_name")
                        .HasFilter("NOT is_deleted");

                    b.ToTable("fuel_types", null, t =>
                        {
                            t.HasCheckConstraint("ck_fuel_types_allow_below_cost_needs_a_cost", "allow_below_cost = false OR supplier_price_per_liter IS NOT NULL");

                            t.HasCheckConstraint("ck_fuel_types_brand_fuel_code_length", "brand_fuel_code IS NULL OR length(brand_fuel_code) <= 50");

                            t.HasCheckConstraint("ck_fuel_types_margin_signs", "margin_uah_per_liter IS NULL OR margin_uah_per_liter >= 0");

                            t.HasCheckConstraint("ck_fuel_types_name_length", "length(name) <= 200");

                            t.HasCheckConstraint("ck_fuel_types_prices_non_negative", "base_price >= 0 AND (discount_price IS NULL OR discount_price > 0)");

                            t.HasCheckConstraint("ck_fuel_types_pricing_knobs_non_negative", "(supplier_price_per_liter IS NULL OR supplier_price_per_liter >= 0) AND (pump_price_per_liter IS NULL OR pump_price_per_liter >= 0) AND (min_discount_per_liter IS NULL OR min_discount_per_liter >= 0)");
                        });

