            modelBuilder.Entity("FuelFlow.SharedKernel.Domain.OrderEvent", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uuid")
                        .HasColumnName("id");

                    b.Property<Guid?>("ActorUserId")
                        .HasColumnType("uuid")
                        .HasColumnName("actor_user_id")
                        .HasComment("Who caused it: a user id, a Telegram staff id, or NULL for a system transition. Not aforeign key - the record has to survive the account.");

                    b.Property<string>("EventType")
                        .IsRequired()
                        .HasMaxLength(40)
                        .HasColumnType("character varying(40)")
                        .HasColumnName("event_type")
                        .HasComment("What happened - 'Created', 'PaymentCaptured', 'Fulfilled', 'Refunded', 'StatusChanged'and the rest. A CHECK pins the vocabulary.");

                    b.Property<string>("ExternalRef")
                        .HasColumnType("text")
                        .HasColumnName("external_ref")
                        .HasComment("The external reference this transition came from - a Monobank invoice id, usually. Keptdenormalised so the same event can be found without joining the order, which is what aduplicate-delivery investigation looks for.");

                    b.Property<string>("FromStatus")
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("from_status")
                        .HasComment("The status before. Set for a status change only. One of the order's eight statuses - a CHECK pins the vocabulary.");

                    b.Property<DateTime>("OccurredAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("occurred_at_utc")
                        .HasComment("When it happened.");

                    b.Property<Guid>("OrderId")
                        .HasColumnType("uuid")
                        .HasColumnName("order_id")
                        .HasComment("The order this happened to.");

                    b.Property<string>("Payload")
                        .HasColumnType("jsonb")
                        .HasColumnName("payload")
                        .HasComment("The raw payload that caused the transition, where one exists (a Monobank webhook body).Kept because reconciling against a statement means being able to see what the acquirersaid, not only what we concluded from it.");

                    b.Property<string>("ToStatus")
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("to_status")
                        .HasComment("The status after. Set for a status change only. One of the order's eight statuses - a CHECK pins the vocabulary.");

                    b.HasKey("Id");

                    b.HasIndex("ExternalRef")
                        .HasDatabaseName("ix_order_events_external_ref");

                    b.HasIndex("OccurredAtUtc")
                        .HasDatabaseName("ix_order_events_occurred_at_utc");

                    b.HasIndex("OrderId", "OccurredAtUtc")
                        .HasDatabaseName("ix_order_events_order_id_occurred_at_utc");

                    b.ToTable("order_events", null, t =>
                        {
                            t.HasCheckConstraint("ck_order_events_event_type", "event_type IN ('Created', 'StatusChanged', 'InvoiceCreated', 'PaymentCaptured', 'Fulfilled', 'PartiallyFulfilled', 'Refunded', 'Cancelled')");

                            t.HasCheckConstraint("ck_order_events_from_to", "(event_type = 'Created' AND from_status IS NULL) OR (event_type <> 'Created' AND to_status IS NOT NULL)");

                            t.HasCheckConstraint("ck_order_events_statuses", "(from_status IS NULL OR from_status IN ('PendingPayment', 'Paid', 'PendingFulfillment', 'PartiallyFulfilled', 'Fulfilled', 'PartiallyRefunded', 'Refunded', 'Cancelled')) AND (to_status IS NULL OR to_status IN ('PendingPayment', 'Paid', 'PendingFulfillment', 'PartiallyFulfilled', 'Fulfilled', 'PartiallyRefunded', 'Refunded', 'Cancelled'))");
                        });
                });

