                    b.HasIndex("Name")
                        .IsUnique()
                        .HasDatabaseName("ix_suppliers_name");

                    b.ToTable("suppliers", null, t =>
                        {
                            t.HasCheckConstraint("ck_suppliers_acquisition_source", "acquisition_source IN ('direct', 'partner')");

                            t.HasCheckConstraint("ck_suppliers_edr_ipn_format", "\"edr_ipn\" IS NULL OR \"edr_ipn\" ~ '^[0-9]{8,10}$'");
                        });
                });

            modelBuilder.Entity("FuelFlow.SharedKernel.Domain.User", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uuid")
                        .HasColumnName("id");

                    b.Property<DateOnly?>("Birthdate")
                        .HasColumnType("date")
                        .HasColumnName("birthdate")
                        .HasComment("The customer's date of birth, when they gave it.");

                    b.Property<decimal>("BonusBalance")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("numeric(12,2)")
                        .HasDefaultValue(0m)
                        .HasColumnName("bonus_balance")
                        .HasComment("The bonus balance in UAH - the money the platform owes the customer. A balance, not a price:it is what is LEFT, and it can be negative when a company has used more than it has paid.");

                    b.Property<DateTime>("CreatedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at_utc")
                        .HasComment("When the account was created.");

                    b.Property<string>("Email")
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("email")
                        .HasComment("The customer's email, when they gave one.");

                    b.Property<string>("FirstName")
                        .HasMaxLength(100)
                        .HasColumnType("character varying(100)")
                        .HasColumnName("first_name")
                        .HasComment("The customer's first name.");

                    b.Property<bool>("IsActive")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("boolean")
                        .HasDefaultValue(false)
                        .HasColumnName("is_active")
                        .HasComment("Whether the account may sign in. Separate from being banned: an inactive account is one thecustomer closed, a banned one is one we closed.");

                    b.Property<bool>("IsBanned")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("boolean")
                        .HasDefaultValue(false)
                        .HasColumnName("is_banned")
                        .HasComment("Whether the account is banned. Separate from being deleted: a banned account keeps itshistory and cannot sign in.");

                    b.Property<bool>("IsDeleted")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("boolean")
                        .HasDefaultValue(false)
                        .HasColumnName("is_deleted")
                        .HasComment("Soft delete. The user stays in the schema, because the orders, the money and the vouchersbehind them have to stay readable.");

                    b.Property<bool>("IsQaAccount")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("boolean")
                        .HasDefaultValue(false)
                        .HasColumnName("is_qa_account")
                        .HasComment("Whether this is a test account. The QA identity is explicitly distinguishable from a realcustomer, and the reports that count customers leave it out.");

                    b.Property<DateTime?>("LastLoginAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("last_login_at_utc")
                        .HasComment("When it last signed in. NULL until it does.");

                    b.Property<string>("LastName")
                        .HasMaxLength(100)
                        .HasColumnType("character varying(100)")
                        .HasColumnName("last_name")
                        .HasComment("The customer's last name.");

                    b.Property<Guid?>("PartyId")
                        .HasColumnType("uuid")
                        .HasColumnName("party_id")
                        .HasComment("The user's party record (D-02, additive step 1). NULLABLE on purpose: the documentedsequence is insert, switch, reconcile, then retire, and this column is the insert.Nothing reads it yet and no handler depends on it, so a user existing without one is notan error today - it becomes one when the column is promoted to NOT NULL, and that is aseparate migration with a test that says so.");

                    b.Property<string>("PendingEmail")
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("pending_email")
                        .HasComment("The address waiting to be confirmed, while the current one still works. NULL when nothingis pending.");

                    b.Property<DateTime?>("PendingEmailExpiresAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("pending_email_expires_at_utc")
                        .HasComment("When the pending address stops being claimable. The token is short-lived on purpose - aconfirmation link that works for a year is a key.");

                    b.Property<string>("PendingEmailTokenHash")
                        .HasMaxLength(100)
                        .HasColumnType("character varying(100)")
                        .HasColumnName("pending_email_token_hash")
                        .HasComment("The HASH of the confirmation token, never the token itself: a database that is read bysomebody must not be able to confirm an address.");

                    b.Property<string>("PhoneNumber")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("phone_number")
                        .HasComment("The customer's phone number, and their identity: the login is the number.");

                    b.Property<string>("ProfileImageUrl")
                        .HasMaxLength(500)
                        .HasColumnType("character varying(500)")
                        .HasColumnName("profile_image_url")
                        .HasComment("Where the avatar is.");

                    b.Property<string>("ReferralCode")
                        .HasMaxLength(50)
                        .HasColumnType("character varying(50)")
                        .HasColumnName("referral_code")
                        .HasComment("The code the customer chose to be referred by. Optional, and it may change - correct formarketing, and deliberately NOT the same thing as the settlement code.");

                    b.Property<string>("ReferredBy")
                        .HasMaxLength(50)
                        .HasColumnType("character varying(50)")
                        .HasColumnName("referred_by")
                        .HasComment("Who referred this customer, in their own words.");

                    b.Property<Guid?>("RoleId")
                        .HasColumnType("uuid")
                        .HasColumnName("role_id")
                        .HasComment("The role this account has, or NULL for an account with no role - which is a state theadmin can repair, not a state the database should refuse.");

                    b.Property<string>("SettlementCode")
                        .ValueGeneratedOnAdd()
                        .HasMaxLength(8)
                        .HasColumnType("character varying(8)")
                        .HasColumnName("settlement_code")
                        .HasComment("The short identifier an operator quotes to the finance channel to attribute money tothis customer. Issued once by the database and immutable for the life of the account: achanged code orphans every payment recorded against it. Deliberately NOT the referralcode - that one is optional and may change, and a customer without one would have no wayto be paid on this route at all. It also avoids the 0/O/1/I/L pairs: it is transcribedby hand, and those are the pairs people misread. A mistyped code credits money to thewrong person, so the alphabet trades a little space for legibility. Staff-only, and itmust not appear in any customer-facing response.");

                    b.Property<int>("TokenVersion")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("integer")
                        .HasDefaultValue(1)
                        .HasColumnName("token_version")
                        .HasComment("The version of the tokens this account's sessions carry. Bumping it invalidates everyrefresh token at once - which is what a password change or a ban has to do, and what nosingle-token revocation can do.");

                    b.Property<DateTime>("UpdatedAtUtc")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at_utc")
                        .HasComment("When it last changed.");

                    b.HasKey("Id");

                    b.HasIndex("PartyId")
                        .HasDatabaseName("ix_users_party_id");

                    b.HasIndex("PhoneNumber")
                        .IsUnique()
                        .HasDatabaseName("ix_users_phone_number")
                        .HasFilter("is_deleted = false");

                    b.HasIndex("ReferralCode")
                        .IsUnique()
                        .HasDatabaseName("ix_users_referral_code")
                        .HasFilter("referral_code IS NOT NULL AND is_deleted = false");

                    b.HasIndex("RoleId")
                        .HasDatabaseName("ix_users_role_id");

                    b.HasIndex("SettlementCode")
                        .IsUnique()
                        .HasDatabaseName("ix_users_settlement_code");

                    b.HasIndex("CreatedAtUtc", "Id")
                        .IsDescending(true, false)
                        .HasDatabaseName("ix_users_created_at_utc_id");

                    b.ToTable("users", null, t =>
                        {
                            t.HasCheckConstraint("ck_users_bonus_balance_non_negative", "bonus_balance >= 0");
                        });
                });

